"""Static HTML provider for the canonical Python web surface."""

from datetime import datetime
import json
from typing import Dict, Optional
from urllib.parse import urlparse

import httpx

from browsefn.core.errors import BrowseFnError
from browsefn.core.types import (
    GetPageOptions,
    PageMetadata,
    PageResult,
    ProviderCapabilities,
)
from browsefn.utils.html_utils import extract_images, extract_links, extract_metadata, extract_text, html_to_markdown, apply_selectors


class BeautifulSoupProvider:
    """Static HTML provider exposed under the canonical `cheerio` id."""

    name = "cheerio"
    capabilities = ProviderCapabilities(
        formats=["html", "markdown", "text", "json"],
        javascript=False,
        screenshots=False,
        cookies=True,
        headers=True,
        selectors=True,
        proxy=True,
    )

    async def get_page(self, url: str, options: GetPageOptions) -> PageResult:
        start_time = datetime.now()
        timeout = (options.timeout or 30000) / 1000
        headers = options.headers or {}
        cookies = httpx.Cookies()
        for cookie in options.cookies or []:
            cookies.set(cookie.name, cookie.value, domain=cookie.domain or urlparse(url).hostname or "", path="/")

        client_config: Dict[str, object] = {
            "timeout": timeout,
            "headers": headers,
            "cookies": cookies,
            "follow_redirects": True,
        }
        if options.proxy:
            client_config["proxy"] = options.proxy

        async with httpx.AsyncClient(**client_config) as client:
            response = await client.get(url)
            response.raise_for_status()
            html_content = response.text
            resolved_url = str(response.url)

        metadata_dict = extract_metadata(html_content)
        metadata = PageMetadata(
            url=resolved_url,
            title=metadata_dict.get("title"),
            description=metadata_dict.get("description"),
            keywords=metadata_dict.get("keywords"),
            author=metadata_dict.get("author"),
            favicon=metadata_dict.get("favicon"),
            openGraph=metadata_dict.get("openGraph"),
            twitter=metadata_dict.get("twitter"),
        )

        if options.selectors:
            html_content = apply_selectors(html_content, options.selectors)

        content_format = options.format or "html"
        if content_format == "html":
            content = html_content
        elif content_format == "markdown":
            content = html_to_markdown(html_content)
        elif content_format == "text":
            content = extract_text(html_content)
        elif content_format == "json":
            content = json.dumps(
                {
                    "title": metadata.title,
                    "description": metadata.description,
                    "links": extract_links(html_content, resolved_url),
                    "images": extract_images(html_content, resolved_url),
                }
            )
        else:
            raise BrowseFnError("INVALID_ARGUMENT", f"Invalid format: {content_format}")

        duration = (datetime.now() - start_time).total_seconds() * 1000

        return PageResult(
            url=resolved_url,
            content=content,
            metadata=metadata,
            links=extract_links(html_content, resolved_url) if options.include_links else None,
            images=extract_images(html_content, resolved_url) if options.include_images else None,
            provider=self.name,
            duration=duration,
        )

    async def is_available(self) -> bool:
        return True
/**
 * Playwright provider for cross-browser scraping.
 */

import type {
  GetPageOptions,
  WebProvider,
} from '../../core/types.js';
import { sanitizeUrl } from '../../utils/validation.js';
import {
  BrowserProviderBase,
  isProviderModuleAvailable,
  useBrowser,
  parseBrowserProxy,
} from './browser-provider-utils.js';

type PlaywrightPage = {
  goto(url: string, options: { waitUntil: string; timeout: number }): Promise<unknown>;
  content(): Promise<string>;
  url(): string;
  screenshot(options: {
    fullPage?: boolean;
    type?: 'png' | 'jpeg';
    quality?: number;
  }): Promise<Uint8Array>;
  evaluate<T>(pageFunction: () => T): Promise<T>;
};

type PlaywrightContext = {
  addCookies(cookies: Array<{ name: string; value: string; domain: string; path: string }>): Promise<void>;
  newPage(): Promise<PlaywrightPage>;
};

type PlaywrightBrowser = {
  newContext(options: {
    extraHTTPHeaders?: Record<string, string>;
    javaScriptEnabled?: boolean;
    userAgent?: string;
    viewport?: { width: number; height: number };
  }): Promise<PlaywrightContext>;
  close(): Promise<void>;
};

type PlaywrightBrowserType = {
  launch(options: { headless: boolean; proxy?: { server: string; username?: string; password?: string } }): Promise<PlaywrightBrowser>;
};

type PlaywrightModule = Record<'chromium' | 'firefox' | 'webkit', PlaywrightBrowserType>;

export class PlaywrightProvider extends BrowserProviderBase<PlaywrightPage> implements WebProvider {
  name = 'playwright';

  private playwright?: PlaywrightModule;

  constructor(
    private config: {
      browser?: 'chromium' | 'firefox' | 'webkit';
      headless?: boolean;
      timeout?: number;
    } = {}
  ) { super(); }

  async isAvailable(): Promise<boolean> {
    return isProviderModuleAvailable(() => this.loadPlaywright());
  }

  protected async withPage<T>(
    url: string,
    options: GetPageOptions,
    callback: (page: PlaywrightPage, sanitizedUrl: string, startedAt: number) => Promise<T>
  ): Promise<T> {
    const playwright = await this.loadPlaywright();
    const startedAt = Date.now();
    const sanitizedUrl = sanitizeUrl(url);

    const browserType = this.config.browser || 'chromium';
    const proxy = parseBrowserProxy(options.proxy);
    const browser = await playwright[browserType].launch({
      headless: this.config.headless ?? true,
      proxy,
    });

    return useBrowser(browser, async () => {
      const context = await browser.newContext({
        extraHTTPHeaders: options.headers,
        javaScriptEnabled: options.javascript,
        userAgent: options.mobile
          ? 'Mozilla/5.0 (iPhone; CPU iPhone OS 14_0 like Mac OS X)'
          : undefined,
        viewport: options.mobile ? { width: 375, height: 667 } : undefined,
      });

      if (options.cookies) {
        await context.addCookies(
          options.cookies.map((cookie) => ({
            name: cookie.name,
            value: cookie.value,
            domain: cookie.domain || new URL(sanitizedUrl).hostname,
            path: '/',
          }))
        );
      }

      const page = await context.newPage();
      const waitUntil =
        options.waitFor === 'networkidle' ? 'networkidle' : options.waitFor || 'load';
      await page.goto(sanitizedUrl, {
        waitUntil,
        timeout: options.timeout || this.config.timeout || 30_000,
      });

      return await callback(page, page.url(), startedAt);
    });
  }
  private async loadPlaywright(): Promise<PlaywrightModule> {
    if (!this.playwright) {
      try {
        const moduleName = 'playwright';
        this.playwright = (await import(moduleName)) as PlaywrightModule;
      } catch {
        throw new Error('Playwright is not installed. Install with: npm install playwright');
      }
    }

    return this.playwright;
  }
}
