    changedPixels: number;
    totalPixels: number;
  },
): Promise<string> {
  const diffDirectory = path.resolve(
    repoRoot,
    artifactRoot,
    'diffs',
    sanitizeBaselineKey(baselineKey),
  );
  await mkdir(diffDirectory, { recursive: true });

  const diffPngPath = path.join(diffDirectory, 'diff.png');
