  }

  private validateDestination(relative: string): string {
    const normalized = assertRepositoryRelativePath(relative);
    if (normalized.startsWith(`${this.artifactRoot}/.quota.sqlite`) || normalized.split('/').includes('.probefn-staging')) throw createProbefnError({ code: 'E_STORAGE_WRITE_FAILED', message: 'Artifact path uses reserved accounting storage.', retryable: false });
